            by.isEmpty }
          val r = own ++ inherited
          memo += (k -> r)
          r })
      }
      for (d <- providedBy(tt.getName, Set()) ++ all.filter(d => !memo.contains(key(d._3.getName))))
        result.add(name, d)
    }
    (result, overridden.reverse)
  }

